      "evidence": {
        "access": "ACTION_CONNECTION_CREATE",
        "object": "10.193.66.115:8080 | event_type=endpoint.event.netconn | parent_path=c:\\windows\\system32\\svchost.exe | parent_cmdline=C:\\Windows\\system32\\svchost.exe -k DcomLaunch | remote_ip=10.193.66.115 | remote_port=8080",
