      "evidence": {
        "access": "ACTION_FILE_CREATE",
        "filemod_name": "c:\\users\\aalsahee\\appdata\\local\\microsoft\\windows\\temporary internet files\\content.ie5\\ckkiicui\\default[1].hta",
        "source_stream": "cbc-ngav"
      }
    },
    {
      "fact": "pid 4724 の直後に spawned された子プロセスとして powershell.exe が観測された。",
      "evidence": {
        "childproc_name": "c:\\windows\\system32\\windowspowershell\\v1.0\\powershell.exe",
        "pid": 4724,
        "ppid": 644,
        "parent_process_name": "svchost.exe",
        "parent_process_path": "c:\\windows\\system32\\svchost.exe",
